/bin/zsh -lc "python3 - <<'PY'
import json, hashlib
from pathlib import Path
from datetime import datetime
for name in ('regras.md', 'eventos.json'):
    print(name, hashlib.sha256(Path(name).read_bytes()).hexdigest())
events = json.loads(Path('eventos.json').read_text())
unique = {}
duplicates = []
for event in events:
    eid = event['event_id']
    if eid in unique:
        assert event == unique[eid], f'Conflicting duplicate: {eid}'
        duplicates.append(eid)
    else:
        unique[eid] = event
start = datetime.fromisoformat('2026-10-10T00:00:00+00:00')
end = datetime.fromisoformat('2026-10-11T00:00:00+00:00')
def instant(event):
    return datetime.fromisoformat(event['em'].replace('Z', '+00:00'))
payments = [e for e in unique.values() if e['tipo'] == 'pago' and e['moeda'] == 'BRL' and start <= instant(e) < end]
channels = {'loja': 0, 'web': 0}
for payment in payments:
    refunds = [e for e in unique.values() if e['pedido'] == payment['pedido'] and e['tipo'] == 'estorno_confirmado' and instant(e) < end]
    net = payment['valor'] - sum(e['valor'] for e in refunds)
    channels[payment['canal']] += net
    print(json.dumps({'pedido': payment['pedido'], 'pagamento': payment['event_id'], 'bruto': payment['valor'], 'estornos': [e['event_id'] for e in refunds], 'liquido': net, 'canal': payment['canal']}, ensure_ascii=False))
print(json.dumps({'registros': len(events), 'eventos_unicos': len(unique), 'duplicatas_descartadas': duplicates, 'pedidos_incluidos': sorted(e['pedido'] for e in payments), 'receita_liquida_centavos': sum(channels.values()), 'por_canal_centavos': channels}, ensure_ascii=False))
PY"

